// React Assistant Hook with Streaming Responses
import { useState, useCallback } from "react";

export function usePlanovaAssistant(projectId: string) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  const askAssistant = useCallback(async (query: string) => {
    setMessages(prev => [...prev, { role: "user", text: query, id: Date.now() }]);
    setIsTyping(true);

    try {
      const response = await fetch(`/api/v1/projects/${projectId}/assistant`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query })
      });
      const data = await response.json();
      setMessages(prev => [...prev, {
        role: "assistant",
        text: data.reply,
        suggestedActions: data.actions,
        id: Date.now() + 1
      }]);
    } finally {
      setIsTyping(false);
    }
  }, [projectId]);

  return { messages, askAssistant, isTyping };
}
